root=pathlib.Path('/workspace/oddments');w=pathlib.Path('/workspace/census-reassessment-e3');e=w/'reports/full-corpus-review/independent-notes/reassessment-e3-evidence';sys.path.insert(0,str(root/'scripts'));import note_review_queue as nq
