for path in [vr['previous_report']['path'],vr['previous_result']['path'],vr['previous_binding']['census_path'],str(rp.relative_to(root))]:assert nq.git(root,'show','HEAD:'+path,binary=True)==(root/path).read_bytes()
check={'checked_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'controller_head':nq.git(root,'rev-parse','HEAD'),'current_root_inventory_unit_binding_exact':True,'current_root_census_and_version_record_committed':True,'worker_base_ledger_may_precede_registration':True,'body_sha256':b['body_sha256'],'final_census_path':b['census_path'],'final_census_raw_sha256':b['census_sha256'],'version_record_path':str(rp.relative_to(root)),'version_record_canonical_sha256':nq.digest(vr),'version_record_raw_sha256':nq.raw_sha(rp.read_bytes()),'old17_json_records_exactly_preserved':True,'original_omissions':oms,'carried_legal_blockers_exact':j['carried_legal_blockers'],'all_prior_report_result_census_bytes_preserved_and_committed':True,'note':'Read-only controller inventory/current/reassessment validation. Old finding used to identify original omission, never as current proposition proof.'};(e/'final-binding-and-original-omission-verification.json').write_text(json.dumps(check,ensure_ascii=False,indent=2)+'\n');print(json.dumps(check,ensure_ascii=False,indent=2))
